s=Path('astra-remaining-improvements/stage/993e7c3b44d7');p=s/'src/lib/game/sessionValidation.js';t=p.read_text(encoding='utf-8').replace('const allLeaves=new Set(initial.board.flatMap(t=>t.leafIds));const groups=initial.groupsByToken;', 'const allLeaves=new Set(initial.board.flatMap(t=>t.leafIds));const originalIds=new Set(initial.board.map(t=>t.id));const leafGroups=new Map(initial.board.flatMap(t=>t.leafIds.map(leaf=>[leaf,t.groupToken])));const groups=initial.groupsByToken;');t=t.replace("typeof tile.id!=='string'||tile.id.length>100", "typeof tile.id!=='string'||!tile.id||(!originalIds.has(tile.id)&&!/^m[1-9]\\d*$/.test(tile.id))||tile.id.length>100");t=t.replace('leaves.add(leaf);', "let expected=leafGroups.get(leaf);for(let level=0;level<tile.level;level++){if(expected===null)fail('tile level exceeds its ancestry.');expected=groups[expected].parentToken;}if(expected!==tile.groupToken)fail('tile contains leaves from a different group.');leaves.add(leaf);");t=t.replace('inspectBoard(value.board);const complete=', "inspectBoard(value.board);if(value.board.some(tile=>/^m[1-9]\\d*$/.test(tile.id)&&Number(tile.id.slice(1))>=value.nextId))fail('merge identity would be reused.');const complete=");p.write_text(t,encoding='utf-8')
