(s/'tests/model.test.js').write_text('''import test from 'node:test';
import assert from 'node:assert/strict';
import {puzzleDraft,dailyFilters,listFilters} from '../src/lib/puzzles/validation.js';
import {buildPuzzlePayload,validateGraph} from '../src/lib/puzzles/payload.js';
import {SAMPLE_PUZZLES} from '../src/lib/puzzles/samplePuzzles.js';
import {createInitialState,applyMerge,undo,consumeHint} from '../src/lib/game/engine.js';
import {serializeState,hydrateState} from '../src/lib/game/reducer.js';
import {readSession,writeSession,resetSession,keyForPuzzle} from '../src/lib/game/storage.js';
import {requireAuthor,readJson,handle,respond} from '../src/lib/http.js';
const sample=()=>structuredClone(SAMPLE_PUZZLES[0]);
const draft=()=>({title:'Learning groups',date:'2026-09-09',locale:'en-US',rootLabel:'Related concepts',categories:Array.from({length:4},(_,i)=>({label:'Category '+i,hint:'',members:Array.from({length:4},(_,j)=>`Word ${i}-${j}`)}))});
const initial=()=>createInitialState(buildPuzzlePayload(sample()));
const memory=(raw=null)=>({raw,getItem(){return this.raw;},setItem(_key,value){this.raw=value;}});
const lock=()=>{let tail=Promise.resolve();return (_key,work)=>{const result=tail.then(work);tail=result.catch(()=>{});return result;};};
test('draft normalization preserves caller and trims editable text',()=>{const value=draft();value.title='  Test title  ';assert.equal(puzzleDraft(value).title,'Test title');assert.equal(value.title,'  Test title  ');});
for(const [name,mutate]of [['blank title',d=>d.title=' '],['too long title',d=>d.title='x'.repeat(121)],['impossible day',d=>d.date='2026-02-30'],['unknown locale',d=>d.locale='xx'],['missing category',d=>d.categories.pop()],['missing word',d=>d.categories[0].members.pop()],['repeated word',d=>d.categories[1].members[0]='WORD 0-0'],['repeated category',d=>d.categories[1].label='CATEGORY 0'],['unknown property',d=>d.isPublished=true],['oversized hint',d=>d.categories[0].hint='x'.repeat(17)]])test('rejects '+name,()=>{const value=draft();mutate(value);assert.throws(()=>puzzleDraft(value));});
test('daily filters reject repeats, unknowns and normalized invalid dates',()=>{for(const raw of ['size=mini&size=big','date=2026-02-30','size=huge','extra=x','locale=','date=2026-2-2'])assert.throws(()=>dailyFilters(new URLSearchParams(raw)));assert.equal(dailyFilters(new URLSearchParams('date=2028-02-29')).date,'2028-02-29');});
test('bounded list filters preserve explicit page and status',()=>{assert.deepEqual(listFilters(new URLSearchParams('q=hello&page=2&status=archived')),{q:'hello',page:2,status:'archived'});for(const raw of ['page=0','page=1e3','page=100000','status=gone','q=a&q=b'])assert.throws(()=>listFilters(new URLSearchParams(raw)));});
test('payload shuffle remains deterministic and preserves all leaves',()=>{for(let i=0;i<80;i++){const value={...sample(),id:'test-'+i};const a=buildPuzzlePayload(value),b=buildPuzzlePayload(value);assert.deepEqual(a,b);assert.equal(a.tiles.length,16);assert.equal(new Set(a.tiles.map(t=>t.leafId)).size,16);assert.ok(a.tiles.every(Boolean));}});
test('graph rejects duplicate IDs, missing parents, cycles and empty internal groups',()=>{for(const mutate of [p=>p.groups[1].id=p.groups[0].id,p=>p.groups[0].parentGroupId='missing',p=>p.groups.at(-1).parentGroupId=p.groups[0].id,p=>p.groups[0].level=2]){const value=sample();mutate(value);assert.throws(()=>validateGraph(value));}});
test('merge engine completes all levels with immutable inputs and undo',()=>{let state=initial();const original=structuredClone(state);const first=state.board[0],second=state.board.find(t=>t.id!==first.id&&t.groupToken===first.groupToken);state=applyMerge(state,first.id,second.id);assert.deepEqual(undo(state).board,original.board);assert.deepEqual(original.board,initial().board);while(state.board.length>1){const a=state.board.find(tile=>state.board.some(other=>other.id!==tile.id&&other.level===tile.level&&other.groupToken===tile.groupToken));assert.ok(a);const b=state.board.find(other=>other.id!==a.id&&other.level===a.level&&other.groupToken===a.groupToken);state=applyMerge(state,a.id,b.id);}assert.equal(state.status,'COMPLETED');assert.equal(state.moveCount,15);assert.equal(hydrateState(initial(),serializeState(state)).status,'COMPLETED');});
test('wrong merge increments mistakes without consuming leaves',()=>{const state=initial(),a=state.board[0],b=state.board.find(t=>t.groupToken!==a.groupToken);const next=applyMerge(state,a.id,b.id);assert.equal(next.mistakes,1);assert.deepEqual(next.board,state.board);});
test('legacy session round trip retains hints, moves and history',()=>{let state=initial();state=consumeHint(state);const a=state.board[0],b=state.board.find(t=>t.id!==a.id&&t.groupToken===a.groupToken);state=applyMerge(state,a.id,b.id);const restored=hydrateState(initial(),serializeState(state));assert.deepEqual(restored.board,state.board);assert.equal(restored.hintsUsed,1);assert.equal(restored.undoStack.length,1);});
for(const [name,mutate]of [['duplicate leaf',s=>s.board[0].leafIds=s.board[1].leafIds],['foreign group',s=>s.board[0].groupToken='missing'],['wrong ancestry',s=>s.board[0].groupToken=s.board.find(t=>t.groupToken!==s.board[0].groupToken).groupToken],['negative mistakes',s=>s.mistakes=-1],['forged completion',s=>s.status='COMPLETED'],['excessive hints',s=>s.hintsUsed=10],['invalid history',s=>s.undoStack=[{}]],['empty ID',s=>s.board[0].id='']])test('session rejects '+name,()=>{const value=serializeState(initial());mutate(value);assert.throws(()=>hydrateState(initial(),value));});
test('corrupt raw data remains available after rejected read',()=>{const storage=memory('{broken');assert.throws(()=>readSession('x',storage));assert.equal(storage.raw,'{broken');});
test('two serialized writers from one baseline produce one accepted write',async()=>{const storage=memory(),coordinator=lock();const results=await Promise.allSettled([writeSession('x',{move:1},null,storage,coordinator),writeSession('x',{move:2},null,storage,coordinator)]);assert.equal(results.filter(r=>r.status==='fulfilled').length,1);assert.equal(readSession('x',storage).saved.move,1);});
test('quota rejection preserves prior raw bytes',async()=>{const storage=memory('old');storage.setItem=()=>{throw new Error('quota');};await assert.rejects(writeSession('x',{},'old',storage,lock()),/quota/);assert.equal(storage.raw,'old');});
test('reset requires raw baseline and creates a new generation',async()=>{const storage=memory();const first=await writeSession('x',{},null,storage,lock());await assert.rejects(resetSession('x',{},null,storage,lock()),/changed/);const next=await resetSession('x',{},first,storage,lock());assert.notEqual(JSON.parse(first).generation,JSON.parse(next).generation);await assert.rejects(writeSession('x',{},first,storage,lock()),/Another tab/);assert.equal(keyForPuzzle('x'),'globs-session:x');});
test('author boundary rejects absent, wrong and cross-origin tokens',()=>{const before=process.env.GLOBS_AUTHOR_TOKEN;process.env.GLOBS_AUTHOR_TOKEN='a'.repeat(64);try{assert.throws(()=>requireAuthor(new Request('http://localhost/api')),/required/);assert.throws(()=>requireAuthor(new Request('http://localhost/api',{headers:{authorization:'Bearer '+'b'.repeat(64)}})),/invalid/);assert.throws(()=>requireAuthor(new Request('http://localhost/api',{headers:{authorization:'Bearer '+'a'.repeat(64),origin:'http://elsewhere'}})),/Cross-origin/);assert.doesNotThrow(()=>requireAuthor(new Request('http://localhost/api',{headers:{authorization:'Bearer '+'a'.repeat(64),origin:'http://localhost'}})));}finally{if(before===undefined)delete process.env.GLOBS_AUTHOR_TOKEN;else process.env.GLOBS_AUTHOR_TOKEN=before;}});
test('body boundary checks content type, JSON and streamed size',async()=>{await assert.rejects(readJson(new Request('http://localhost',{method:'POST',body:'{}'})),/application\/json/);await assert.rejects(readJson(new Request('http://localhost',{method:'POST',headers:{'content-type':'application/json'},body:'{bad'})),/valid JSON/);await assert.rejects(readJson(new Request('http://localhost',{method:'POST',headers:{'content-type':'application/json'},body:' '.repeat(32769)})),/32 KiB/);assert.deepEqual(await readJson(new Request('http://localhost',{method:'POST',headers:{'content-type':'application/json'},body:'{"ok":true}'})),{ok:true});});
test('HTTP error mapping retains a request ID and hides raw database details',async()=>{const response=await handle(new Request('http://localhost'),()=>{const e=new Error('private SQL details');e.code='P2002';throw e;},{author:false});assert.equal(response.status,409);const body=await response.json();assert.ok(body.requestId);assert.equal(response.headers.get('X-Request-Id'),body.requestId);assert.ok(!JSON.stringify(body).includes('private'));assert.equal(respond({ok:true}).headers.get('cache-control'),'no-store');});
''',encoding='utf-8');print('Added model, failure-boundary and concurrency tests')
